from math import gcd, log2
from typing import Dict


def factorise(n: int) -> Dict[int, int]:
    """Prime factorisation of n >= 1 as {prime: exponent}, by trial division."""
    factors: Dict[int, int] = {}
    m, k = n, 2
    while k * k <= m:
        while m % k == 0:
            factors[k] = factors.get(k, 0) + 1
            m //= k
        k += 1
    if m > 1:
        factors[m] = factors.get(m, 0) + 1
    return factors


def ipair_two_power(k: int) -> float:
    """Closed form Ipair(2^k) = (4/3)(1 - 4^{-k})."""
    return (4.0 / 3.0) * (1.0 - 4.0 ** (-k))


def ipair_fast(n: int, direct) -> float:
    """Ipair(n) via the Chinese Remainder decomposition into primary components.

    Uses Ipair(mn) = Ipair(m) + Ipair(n) for coprime m, n, the closed form for
    the 2-primary part, and the caller-supplied Theta(p^{2e}) direct evaluator
    for the odd parts.  Cost sum_{p^e || n} p^{2e} instead of n^2, which makes
    moduli such as 3^2*5*7*11*13*17*19*23*29*31 instantaneous.
    """
    total = 0.0
    for p, e in factorise(n).items():
        total += ipair_two_power(e) if p == 2 else direct(p ** e)
    return total
